import { PrismaClient, type Prisma } from "./generated/prisma/client";
import { createPrismaAdapter } from "./prismaAdapter";

type AppPrismaClientOptions = Prisma.PrismaClientOptions & {
  log: Array<Prisma.LogLevel | Prisma.LogDefinition>;
  omit?: never;
};

const client = new PrismaClient<
  AppPrismaClientOptions, "query", undefined
>({
  adapter: createPrismaAdapter(),
  log: [{ level: "query", emit: "event" }],
});

// The exported type alias has different generic positions.
type AppClient = PrismaClient<never, undefined>;
